# Cloud Storage bucket configured to automatically delete objects after 90 days
resource "google_storage_bucket" "auto_expire_bucket" {
  name     = "example-auto-expire-90-days-bucket"
  location = "US"

  # Enforce IAM-only access control
  uniform_bucket_level_access = true

  # Lifecycle rule to delete objects 90 days after creation
  lifecycle_rule {
    condition {
      age = 90
    }
    action {
      type = "Delete"
    }
  }

  labels = {
    lifecycle_policy = "delete-90-days"
    managed_by       = "terraform"
  }
}

