# Service account for reading objects from the storage bucket
resource "google_service_account" "storage_reader" {
  account_id   = "storage-object-reader"
  display_name = "Storage Object Reader Service Account"
  description  = "Service account with read-only access to objects in the target Cloud Storage bucket"
}

# Private Cloud Storage bucket with secure defaults
resource "google_storage_bucket" "private_bucket" {
  name          = "secure-storage-bucket-${google_service_account.storage_reader.unique_id}"
  location      = "US"
  force_destroy = false

  # Ensure uniform bucket-level access is enabled for consistent IAM control
  uniform_bucket_level_access = true

  # Prevent accidental public exposure
  public_access_prevention = "enforced"

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

# Grant the service account read-only object access to the bucket
resource "google_storage_bucket_iam_member" "reader_object_viewer" {
  bucket = google_storage_bucket.private_bucket.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.storage_reader.email}"
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Default project and region can be provided via environment variables or configured here.
}

# VPC network required to host private IP connectivity for Cloud SQL
resource "google_compute_network" "default" {
  name                    = "cloud-sql-vpc"
  auto_create_subnetworks = false
}

# Subnet for general workloads within the VPC
resource "google_compute_subnetwork" "default" {
  name          = "cloud-sql-subnet"
  ip_cidr_range = "10.0.0.0/24"
  region        = "us-central1"
  network       = google_compute_network.default.id
}

# Reserved internal IP address range for Service Networking (Cloud SQL private services access)
resource "google_compute_global_address" "private_ip_alloc" {
  name          = "cloud-sql-private-ip-alloc"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.default.id
}

# Establish private services access connection to Google services
resource "google_service_networking_connection" "private_vpc_connection" {
  network                 = google_compute_network.default.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.private_ip_alloc.name]
}

# PostgreSQL Cloud SQL instance with private IP only and deletion protection enabled
resource "google_sql_database_instance" "default" {
  name                = "postgres-private-instance"
  database_version    = "POSTGRES_15"
  region              = "us-central1"
  deletion_protection = true

  # Ensure the private VPC peering connection is established before instance creation
  depends_on = [google_service_networking_connection.private_vpc_connection]

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.default.id
    }

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "google" {
  # Configuration options such as project and region can be set here
  # or via environment variables (e.g., GOOGLE_PROJECT, GOOGLE_REGION).
}

# Suffix to ensure uniqueness of the instance name
resource "random_id" "instance_suffix" {
  byte_length = 4
}

# Strong random password for the database user
resource "random_password" "db_password" {
  length  = 24
  special = true
}

# Cloud SQL PostgreSQL Instance
resource "google_sql_database_instance" "main" {
  name                = "postgres-instance-${random_id.instance_suffix.hex}"
  database_version    = "POSTGRES_15"
  region              = "us-central1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      # Secure default: disable public IPv4 access unless private VPC connection is configured
      ipv4_enabled = false
    }
  }
}

# PostgreSQL Database
resource "google_sql_database" "appdb" {
  name     = "appdb"
  instance = google_sql_database_instance.main.name
}

# PostgreSQL User
resource "google_sql_user" "appuser" {
  name     = "appuser"
  instance = google_sql_database_instance.main.name
  password = random_password.db_password.result
}

