data "google_project" "current" {}

# Dedicated VPC network for the private GKE cluster
resource "google_compute_network" "vpc" {
  name                    = "gke-vpc"
  auto_create_subnetworks = false
}

# Subnet configured with secondary ranges for VPC-native GKE IP allocation
resource "google_compute_subnetwork" "subnet" {
  name                     = "gke-subnet"
  ip_cidr_range            = "10.0.0.0/20"
  region                   = "us-central1"
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "pods"
    ip_cidr_range = "10.4.0.0/14"
  }

  secondary_ip_range {
    range_name    = "services"
    ip_cidr_range = "10.8.0.0/20"
  }
}

# Dedicated service account for GKE node pool VMs following least-privilege principles
resource "google_service_account" "gke_nodes" {
  account_id   = "gke-node-sa"
  display_name = "GKE Node Pool Service Account"
}

# Regional private GKE cluster with Workload Identity enabled
resource "google_container_cluster" "primary" {
  name     = "private-gke-cluster"
  location = "us-central1"

  network    = google_compute_network.vpc.self_link
  subnetwork = google_compute_subnetwork.subnet.self_link

  # Remove default node pool immediately to use a dedicated, managed node pool
  remove_default_node_pool = true
  initial_node_count       = 1

  # VPC-native networking setup
  ip_allocation_policy {
    cluster_secondary_range_name  = "pods"
    services_secondary_range_name = "services"
  }

  # Private cluster configuration: nodes receive only private RFC 1918 IPs
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # Workload Identity configuration
  workload_identity_config {
    workload_pool = "${data.google_project.current.project_id}.svc.id.goog"
  }

  # Recommended release channel over pinning specific versions
  release_channel {
    channel = "REGULAR"
  }

  # Protect against accidental deletion
  deletion_protection = false
}

# Separately managed node pool
resource "google_container_node_pool" "primary_nodes" {
  name       = "primary-node-pool"
  cluster    = google_container_cluster.primary.name
  location   = google_container_cluster.primary.location
  node_count = 2

  node_config {
    machine_type    = "e2-medium"
    service_account = google_service_account.gke_nodes.email

    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    labels = {
      environment = "production"
    }

    # Restrict metadata access to prevent extraction of instance metadata
    metadata = {
      disable-legacy-endpoints = "true"
    }
  }
}

