# Dedicated service account following the principle of least privilege
resource "google_service_account" "node_pool_sa" {
  account_id   = "main-cluster-np-sa"
  display_name = "Service Account for main-cluster autoscaling node pool"
}

# GKE Node Pool configured for an existing cluster named 'main-cluster'
resource "google_container_node_pool" "autoscaling_node_pool" {
  name     = "autoscaling-node-pool"
  cluster  = "main-cluster"
  location = "asia-south1"

  # Initial node count when created; autoscaling manages sizing thereafter
  initial_node_count = 1

  autoscaling {
    min_node_count = 1
    max_node_count = 5
  }

  management {
    auto_repair  = true
    auto_upgrade = true
  }

  node_config {
    machine_type    = "e2-medium"
    service_account = google_service_account.node_pool_sa.email

    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    metadata = {
      disable-legacy-endpoints = "true"
    }
  }

  lifecycle {
    ignore_changes = [
      initial_node_count
    ]
  }
}

