  name                    = "custom-vpc"
  auto_create_subnetworks = false
}

# Firewall rule allowing inbound SSH (TCP port 22) only from the designated IP range
resource "google_compute_firewall" "allow_ssh_from_trusted_range" {
  name        = "allow-ssh-from-trusted"
  network     = google_compute_network.custom_network.name
  description = "Allows inbound TCP port 22 traffic only from 203.0.113.0/24"

  direction     = "INGRESS"
  source_ranges = ["203.0.113.0/24"]

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }
}

