  machine_type = "e2-medium"
  zone         = "us-central1-a"

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-11"
      labels = {
        environment = "production"
      }
    }
  }

  # Omitting the access_config block inside network_interface ensures no public/external IP is assigned
  network_interface {
    network    = google_compute_network.vpc_network.id
    subnetwork = google_compute_subnetwork.subnet.id
  }

  service_account {
    # Attach dedicated custom service account with cloud-platform scope (permissions managed via IAM roles)
    email  = google_service_account.vm_service_account.email
    scopes = ["cloud-platform"]
  }

  labels = {
    environment = "production"
  }
}

