variable "office_vpn_cidr" {
  type        = string
  description = "The public IP CIDR range of the office VPN allowed to connect to Cloud SQL"
  default     = "203.0.113.0/24" # Example documentation range; update with actual office VPN CIDR
}

resource "google_sql_database_instance" "mysql_public" {
  name                = "mysql-public-instance"
  database_version    = "MYSQL_8_0"
  region              = "us-central1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-7680"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      # Public IP explicitly enabled per requirement
      ipv4_enabled = true

      # Enforce encrypted connections over the public IP
      ssl_mode = "ENCRYPTED_ONLY"

      # Restrict public network access to authorized networks (office VPN)
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }
  }
}

output "public_ip_address" {
  description = "The public IPv4 address assigned to the Cloud SQL instance"
  value       = google_sql_database_instance.mysql_public.public_ip_address
}

