# Terraform configuration for a private PostgreSQL Cloud SQL instance

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Default provider configuration
}

# The retrieved context specifies that when ipv4_enabled is false, a private_network
# must be configured. Setting up the VPC and Private Services Access connection below,
# which are required by Cloud SQL to allocate private IP addresses.
resource "google_compute_network" "private_network" {
  name                    = "cloud-sql-vpc"
  auto_create_subnetworks = true
}

# Reserve an IP range for Cloud SQL private services access peering
resource "google_compute_global_address" "private_ip_alloc" {
  name          = "cloud-sql-private-ip-alloc"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.private_network.id
}

# Establish private VPC peering connection to Google services
resource "google_service_networking_connection" "private_vpc_connection" {
  network                 = google_compute_network.private_network.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.private_ip_alloc.name]
}

# PostgreSQL Cloud SQL Instance with private IP and deletion protection enabled
resource "google_sql_database_instance" "postgres" {
  name                = "postgres-private-instance"
  database_version    = "POSTGRES_15"
  region              = "us-central1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.private_network.self_link
      ssl_mode        = "ENCRYPTED_ONLY"
    }
  }

  depends_on = [google_service_networking_connection.private_vpc_connection]
}

