provider "google" {
  # Configuration options such as project and region can also be supplied via environment variables
}

variable "project_id" {
  description = "The GCP project ID to host the Cloud SQL instance."
  type        = string
}

variable "region" {
  description = "The region where Cloud SQL will be deployed."
  type        = string
  default     = "us-central1"
}

variable "instance_name" {
  description = "The name of the Cloud SQL instance."
  type        = string
  default     = "app-postgres-instance"
}

variable "appuser_password" {
  description = "The password for the PostgreSQL appuser."
  type        = string
  sensitive   = true
}

# PostgreSQL Database Instance
resource "google_sql_database_instance" "default" {
  name                = var.instance_name
  database_version    = "POSTGRES_15"
  region              = var.region
  project             = var.project_id
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      # No authorized networks specified to prevent direct public internet access
      ipv4_enabled = true
    }
  }
}

