# Single Terraform configuration for a MySQL Cloud SQL instance with a public IP
# configured for authorized network access (e.g., Office VPN) and enforced encryption.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Credentials and project can be configured via environment variables or provider defaults
}

variable "office_vpn_cidr" {
  type        = string
  description = "The CIDR block of the office VPN allowed to access the Cloud SQL instance"
  default     = "198.51.100.0/24" # Replace with actual office VPN CIDR
}

resource "google_sql_database_instance" "mysql_instance" {
  name                = "mysql-public-instance"
  database_version    = "MYSQL_8_0"
  region              = "us-central1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-7680"
    availability_type = "REGIONAL"

    # Automated backups and binary logging for point-in-time recovery on MySQL
    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    ip_configuration {
      # Explicitly enabled per requirement: office VPN connects directly over public IP
      ipv4_enabled = true

      # Enforce SSL/TLS for all connections over public IP
      ssl_mode = "ENCRYPTED_ONLY"

      # Restrict public IP access strictly to authorized IPs (Least Privilege)
      authorized_networks {
        name  = "office-vpn"
