    environment = "production"
    managed_by  = "terraform"
  }

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      labels = {
        environment = "production"
      }
    }
  }

  network_interface {
    subnetwork = google_compute_subnetwork.subnet.id

