}

# Cloud Scheduler job configured to publish to the Pub/Sub topic every day at 02:00 UTC
resource "google_cloud_scheduler_job" "daily_pubsub_job" {
  name        = "daily-pubsub-trigger"
  description = "Triggers a Pub/Sub message daily at 02:00 UTC"
  schedule    = "0 2 * * *"
  time_zone   = "Etc/UTC"

  pubsub_target {
    topic_name = google_pubsub_topic.scheduled_topic.id
    data       = base64encode(jsonencode({
      source    = "cloud-scheduler"
      timestamp = "daily-run"
      action    = "trigger"
    }))
  }
}

