variable "office_vpn_cidr" {
  description = "Public IP address or CIDR range of the office VPN allowed to connect to Cloud SQL"
  type        = string
  default     = "203.0.113.0/24" # Example CIDR range; replace with actual office VPN public IP
}

resource "google_sql_database_instance" "mysql_public" {
  name             = "mysql-public-instance"
  database_version = "MYSQL_8_0"
  region           = "us-central1"

  # Production safeguards
  deletion_protection = true

  settings {
    tier              = "db-custom-2-7680"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true # Required for MySQL point-in-time recovery
    }

    ip_configuration {
      # Explicitly requested public IP access
      ipv4_enabled = true

      # Enforce SSL/TLS encryption for all incoming connections over the public IP
      ssl_mode = "ENCRYPTED_ONLY"

      # Restrict public network ingress strictly to the office VPN IP/CIDR
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }

    user_labels = {
      environment = "production"
      managed_by  = "terraform"
    }
  }
}

output "public_ip_address" {
  description = "The public IPv4 address assigned to the Cloud SQL instance"
  value       = google_sql_database_instance.mysql_public.public_ip_address
}
